INSERT INTO feature VALUES('content-addressed-references','kernel','Content-addressed kernel references','check-memo','partial','notable',NULL,'A memo key names a reference to a plain definition — checked, alone, outside every atom''s minting admission, monomorphic and carrying no laws, relations, rules, stages, presentation or provenance — by its declared type, its body and its rank among the earlier definitions of that content, so two environments that admitted the same declarations in another order build one key; every other constant is still named by its position (#3001).','kernel-core kernel-core-base','crates/kernel-core-base/src/encoding.rs',NULL,'#3001');
